def algorithm(func, dim, lb, ub, budget, rng):
    def bound(x):
        return np.clip(x, lb, ub)

    x = np.random.uniform(lb, ub, (dim,))
    best_x = x.copy()
    best_fitness = func(x)

    adaptive_mut_rate = 0.1
    adaptive_crossover_rate = 0.5

    for i in range(budget):
        y = bound(x + rng.normal(0, 1, (dim,)))
        fitness = func(y)

        if fitness < best_fitness:
            best_x = y.copy()
            best_fitness = fitness

        mutant_prob = adaptive_mut_rate / (adaptive_mut_rate + np.exp(-i))
        crossover_prob = adaptive_crossover_rate / (adaptive_crossover_rate + np.exp(-i))

        for j in range(dim):
            if rng.random() < mutant_prob:
                y[j] = bound(y[j] + rng.uniform(-1, 1))

            if rng.random() < crossover_prob:
                x[j], y[j] = y[j], x[j]

        x = y.copy()

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def generate_candidate(current_best, rng=rng):
        noise = rng.normal(size=dim)
        return current_best + 0.1 * noise

    current_best = np.random.uniform(lb, ub, size=dim)
    current_best = clip(current_best)

    for _ in range(budget):
        candidate = generate_candidate(current_best, rng=rng)
        candidate = clip(candidate)

        if func(candidate) < func(current_best):
            current_best = candidate

        # Simulated annealing
        alpha = 0.9 * np.exp(-1 / (budget + 1))
        beta = np.random.uniform(0, 1)
        if beta > alpha:
            candidate = generate_candidate(current_best, rng=rng)
            candidate = clip(candidate)

        if func(candidate) < func(current_best):
            current_best = candidate

    return current_best
